    // (a-b) is within [-99, 99], so abs is within [0, 99]; x <= 100 => sum within [0, 199]
    let raw = dist + x;
    let cap = n - 1;
    let ans = min_i8(raw, cap);

    // Prove range postcondition:
    // ans <= cap = n-1 and n>=2 => n-1 >= 1 => ans >= 0 because dist>=0 and x>=0.
    assert(dist >= 0);
    assert(raw >= 0);
    assert(cap >= 1);

